public class Main {
    static final long MOD = 1000000007;
    static final int MAXK = 10000;

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }

    static long inv(long a) {
        return modPow(a % MOD, MOD - 2);
    }

    // Precompute factorials and inverse factorials up to MAXK
    static long[] fact = new long[MAXK + 1];
    static long[] ifact = new long[MAXK + 1];

    static void precomputeFact() {
        fact[0] = 1;
        for (int i = 1; i <= MAXK; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        ifact[MAXK] = inv(fact[MAXK]);
        for (int i = MAXK - 1; i >= 0; i--) {
            ifact[i] = ifact[i + 1] * (i + 1) % MOD;
        }
    }

    static long comb(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n] * ifact[k] % MOD * ifact[n - k] % MOD;
    }

    // Factorize n into prime factors
    static long[] primes;
    static int[] exps;

    static void factorize(long n) {
        List<Long> pList = new ArrayList<>();
        List<Integer> eList = new ArrayList<>();
        for (long i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                int cnt = 0;
                while (n % i == 0) {
                    n /= i;
                    cnt++;
                }
                pList.add(i);
                eList.add(cnt);
            }
        }
        if (n > 1) {
            pList.add(n);
            eList.add(1);
        }
        primes = new long[pList.size()];
        exps = new int[eList.size()];
        for (int i = 0; i < pList.size(); i++) {
            primes[i] = pList.get(i);
            exps[i] = eList.get(i);
        }
    }

    // Compute expected value contribution for a single prime p with exponent e over k steps
    static long computePrimeContribution(long p, int e, int k) {
        // dp[t][x] = probability of being at exponent x after t steps
        // We use a 1D array and update in place
        long[] dp = new long[e + 1];
        dp[e] = 1; // start at exponent e

        for (int step = 0; step < k; step++) {
            long[] ndp = new long[e + 1];
            for (int x = 0; x <= e; x++) {
                if (dp[x] == 0) continue;
                // Number of divisors of p^x is x+1
                long invDiv = inv(x + 1);
                for (int y = 0; y <= x; y++) {
                    ndp[y] = (ndp[y] + dp[x] * invDiv) % MOD;
                }
            }
            dp = ndp;
        }

        // Expected value contribution: sum over x of p^x * dp[x]
        long contrib = 0;
        long pPow = 1;
        for (int x = 0; x <= e; x++) {
            contrib = (contrib + pPow * dp[x]) % MOD;
            pPow = pPow * p % MOD;
        }
        return contrib;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        long n = Long.parseLong(parts[0]);
        int k = Integer.parseInt(parts[1]);

        precomputeFact();
        factorize(n);

        long result = 1;
        for (int i = 0; i < primes.length; i++) {
            long contrib = computePrimeContribution(primes[i], exps[i], k);
            result = result * contrib % MOD;
        }

        System.out.println(result);
    }
}
