    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long n = fs.nextLong();
        int k = fs.nextInt();

        // Factorize n
        Map<Long, Integer> factors = new HashMap<>();
        long temp = n;
        for (int p : primes) {
            if ((long) p * p > temp) break;
            if (temp % p == 0) {
                int cnt = 0;
                while (temp % p == 0) {
                    cnt++;
                    temp /= p;
                }
                factors.put((long) p, cnt);
            }
        }
        if (temp > 1) {
            factors.put(temp, 1);
        }

        long ans = 1;
        for (Map.Entry<Long, Integer> entry : factors.entrySet()) {
            long p = entry.getKey();
            int e = entry.getValue();
            ans = ans * compute(p, e, k) % MOD;
        }
        System.out.println(ans);
    }

    // Compute expected value contribution for prime p with exponent e over k steps
    static long compute(long p, int e, int k) {
        // dp[t][x] = probability of being in state x after t steps
        // x ranges from 0 to e
        long[][] dp = new long[k + 1][e + 1];
        dp[0][e] = 1;

        for (int t = 0; t < k; t++) {
            for (int x = 0; x <= e; x++) {
                if (dp[t][x] == 0) continue;
                // Number of divisors with exponent y is (y+1) for each prime factor
                // But since we're only tracking one prime, the number of divisors with exponent y is 1
                // Wait, no. The total number of divisors of the current number (which is p^x) is x+1
                // Each divisor corresponds to choosing exponent y from 0 to x
                // So probability of choosing y is 1/(x+1)
                long prob = dp[t][x] * inv(x + 1) % MOD;
                for (int y = 0; y <= x; y++) {
                    dp[t + 1][y] = (dp[t + 1][y] + prob) % MOD;
                }
            }
        }

        // Expected value = sum over x of p^x * dp[k][x]
        long result = 0;
        long pmod = p % MOD;
        long ppower = 1;
        for (int x = 0; x <= e; x++) {
            result = (result + ppower * dp[k][x]) % MOD;
            ppower = ppower * pmod % MOD;
        }
        return result;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr < buflen) return buffer[ptr++];
            buflen = in.read(buffer);
            ptr = 0;
            return buflen == -1 ? -1 : buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c = readByte();
            while (c <= ' ') c = readByte();
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return neg ? -val : val;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
