    static final long MOD = 1000000007;
    static final long INV2 = 500000004; // Modular inverse of 2 mod MOD

    // Compute modular inverse using Fermat's little theorem
    static long modInv(long a, long mod) {
        return BigInteger.valueOf(a).modInverse(BigInteger.valueOf(mod)).longValue();
    }

    // Factorize n into primes and exponents
    static Map<Long, Integer> factorize(long n) {
        Map<Long, Integer> factors = new HashMap<>();
        for (long i = 2; i * i <= n; i++) {
            while (n % i == 0) {
                factors.put(i, factors.getOrDefault(i, 0) + 1);
                n /= i;
            }
        }
        if (n > 1) {
            factors.put(n, 1);
        }
        return factors;
    }

    // Compute the expected value for a single prime power p^a after k steps
    static long computeEV(long p, int a, int k) {
        long[][] dp = new long[k+1][a+1];
        for (int x = 0; x <= a; x++) {
            dp[0][x] = 1;
        }
        for (int step = 1; step <= k; step++) {
            for (int x = 0; x <= a; x++) {
                long sum = 0;
                for (int y = 0; y <= x; y++) {
                    sum = (sum + dp[step-1][y]) % MOD;
                }
                dp[step][x] = sum * modInv(x + 1, MOD) % MOD;
            }
        }
        return dp[k][a];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        long n = Long.parseLong(parts[0]);
        int k = Integer.parseInt(parts[1]);

        Map<Long, Integer> factors = factorize(n);
        long result = 1;
        for (Map.Entry<Long, Integer> entry : factors.entrySet()) {
            long p = entry.getKey();
            int a = entry.getValue();
            long ev = computeEV(p, a, k);
            result = result * ev % MOD;
        }
        System.out.println(result);
    }
